package net.bisosrs.profileexport;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.ActionEvent;
import javax.inject.Inject;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.bisosrs.profileexport.BisOsrsProfileExporter.ExportResult;
import net.bisosrs.profileexport.util.ExportActions;
import net.runelite.api.Client;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class BisOsrsPanel extends PluginPanel
{
	private final BisOsrsProfileExporter exporter;
	private final Client client;

	private final JLabel statusLabel = new JLabel("Log in, then refresh export preview.", SwingConstants.LEFT);
	private final JLabel statsLabel = new JLabel("Stats: —", SwingConstants.LEFT);
	private final JLabel questsLabel = new JLabel("Quests: —", SwingConstants.LEFT);
	private final JLabel diariesLabel = new JLabel("Diaries: —", SwingConstants.LEFT);
	private final JLabel ownedLabel = new JLabel("Owned items: —", SwingConstants.LEFT);
	private final JLabel accountLabel = new JLabel("Account type: —", SwingConstants.LEFT);

	private ExportResult lastExport;

	@Inject
	BisOsrsPanel(BisOsrsProfileExporter exporter, Client client)
	{
		super(false);
		this.exporter = exporter;
		this.client = client;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("BIS OSRS Quest Exporter");
		title.setForeground(Color.WHITE);

		JPanel summaryPanel = new JPanel(new GridLayout(0, 1, 0, 4));
		summaryPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summaryPanel.setBorder(new EmptyBorder(8, 8, 8, 8));

		JLabel summaryHeading = new JLabel("Export summary");
		summaryHeading.setForeground(Color.LIGHT_GRAY);
		summaryPanel.add(summaryHeading);
		styleSummaryLabel(statsLabel);
		styleSummaryLabel(questsLabel);
		styleSummaryLabel(diariesLabel);
		styleSummaryLabel(ownedLabel);
		styleSummaryLabel(accountLabel);
		summaryPanel.add(statsLabel);
		summaryPanel.add(questsLabel);
		summaryPanel.add(diariesLabel);
		summaryPanel.add(ownedLabel);
		summaryPanel.add(accountLabel);

		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 6));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton refreshButton = new JButton("Refresh preview");
		refreshButton.addActionListener(this::refreshPreview);

		JButton copyButton = new JButton("Copy BIS OSRS JSON");
		copyButton.addActionListener(this::copyJson);

		JButton saveButton = new JButton("Save BIS OSRS JSON");
		saveButton.addActionListener(this::saveJson);

		buttons.add(refreshButton);
		buttons.add(copyButton);
		buttons.add(saveButton);

		JPanel north = new JPanel(new BorderLayout(0, 8));
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);
		north.add(title, BorderLayout.NORTH);
		north.add(summaryPanel, BorderLayout.CENTER);
		north.add(buttons, BorderLayout.SOUTH);

		statusLabel.setForeground(Color.LIGHT_GRAY);
		statusLabel.setPreferredSize(new Dimension(0, 40));

		add(north, BorderLayout.NORTH);
		add(statusLabel, BorderLayout.SOUTH);
	}

	private void styleSummaryLabel(JLabel label)
	{
		label.setForeground(Color.WHITE);
	}

	private void refreshPreview(ActionEvent event)
	{
		lastExport = exporter.exportProfile();
		if (!lastExport.isOk())
		{
			statusLabel.setText(lastExport.getMessage());
			statsLabel.setText("Stats: —");
			questsLabel.setText("Quests: —");
			diariesLabel.setText("Diaries: —");
			ownedLabel.setText("Owned items: —");
			accountLabel.setText("Account type: —");
			return;
		}

		ExportSummary summary = lastExport.getSummary();
		statsLabel.setText(summary.statsLine());
		questsLabel.setText(summary.questsLine());
		diariesLabel.setText(summary.diariesLine());
		ownedLabel.setText(summary.ownedItemsLine());
		accountLabel.setText(summary.accountTypeLine());
		statusLabel.setText(summary.getStatusMessage());
	}

	private void copyJson(ActionEvent event)
	{
		ExportResult result = ensureExport();
		if (!result.isOk())
		{
			statusLabel.setText(result.getMessage());
			return;
		}

		ExportActions.copyToClipboard(result.getJson());
		statusLabel.setText("JSON copied to clipboard.");
	}

	private void saveJson(ActionEvent event)
	{
		ExportResult result = ensureExport();
		if (!result.isOk())
		{
			statusLabel.setText(result.getMessage());
			return;
		}

		try
		{
			String username = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : "";
			java.io.File file = ExportActions.saveToFile(result.getJson(), username);
			if (file != null)
			{
				statusLabel.setText("Saved " + file.getName());
			}
		}
		catch (Exception e)
		{
			statusLabel.setText("Save failed: " + e.getMessage());
		}
	}

	private ExportResult ensureExport()
	{
		if (lastExport != null && lastExport.isOk())
		{
			return lastExport;
		}
		lastExport = exporter.exportProfile();
		if (lastExport.isOk())
		{
			refreshPreview(null);
		}
		return lastExport;
	}
}

package net.bisosrs.profileexport;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
	name = "BIS OSRS Quest Exporter",
	description = "Read-only JSON export of stats, quests, diaries, and equipped untradeables for BIS OSRS",
	tags = {"bis", "gear", "export", "profile", "quests", "read-only"}
)
public class BisOsrsPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private BisOsrsPanel panel;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
		if (icon == null)
		{
			icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		}

		navButton = NavigationButton.builder()
			.tooltip("BIS OSRS Quest Exporter")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("BIS OSRS Quest Exporter started");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		log.debug("BIS OSRS Quest Exporter stopped");
	}

	@Provides
	BisOsrsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BisOsrsConfig.class);
	}
}

package net.bisosrs.profileexport;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Value;

@Value
@Builder
public class BisOsrsProfile
{
	public static final int EXPORT_VERSION = 1;
	public static final String EXPORT_SOURCE = "runelite-plugin";
	public static final String SCHEMA_VERSION_LABEL = "2026-05";

	int version;
	String source;
	String exportedAt;
	String notes;
	BisOsrsStats stats;
	List<String> completedQuestIds;
	List<BisOsrsDiaryTier> completedDiaryTiers;
	List<String> completedUnlockIds;
	List<Integer> ownedItemIds;
	List<String> ownedItemNames;
	List<String> ownedItemLines;
	String accountType;
	String schemaVersionLabel;

	public static BisOsrsProfile emptyShell()
	{
		return BisOsrsProfile.builder()
			.version(EXPORT_VERSION)
			.source(EXPORT_SOURCE)
			.exportedAt("")
			.notes("")
			.stats(BisOsrsStats.empty())
			.completedQuestIds(Collections.emptyList())
			.completedDiaryTiers(Collections.emptyList())
			.completedUnlockIds(Collections.emptyList())
			.ownedItemIds(Collections.emptyList())
			.ownedItemNames(Collections.emptyList())
			.ownedItemLines(Collections.emptyList())
			.accountType("unknown")
			.schemaVersionLabel(SCHEMA_VERSION_LABEL)
			.build();
	}

	public BisOsrsProfile withMutableCollections()
	{
		return BisOsrsProfile.builder()
			.version(version)
			.source(source)
			.exportedAt(exportedAt)
			.notes(notes)
			.stats(stats)
			.completedQuestIds(new ArrayList<>(completedQuestIds))
			.completedDiaryTiers(new ArrayList<>(completedDiaryTiers))
			.completedUnlockIds(new ArrayList<>(completedUnlockIds))
			.ownedItemIds(new ArrayList<>(ownedItemIds))
			.ownedItemNames(new ArrayList<>(ownedItemNames))
			.ownedItemLines(new ArrayList<>(ownedItemLines))
			.accountType(accountType)
			.schemaVersionLabel(schemaVersionLabel)
			.build();
	}
}

package net.bisosrs.profileexport;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.bisosrs.profileexport.mapping.AccountTypeMapper;
import net.bisosrs.profileexport.mapping.BisCatalog;
import net.bisosrs.profileexport.mapping.DiaryCollector;
import net.bisosrs.profileexport.mapping.EquippedUntradeablesCollector;
import net.bisosrs.profileexport.mapping.EquippedUntradeablesCollector.OwnedItemExport;
import net.bisosrs.profileexport.mapping.QuestCollector;
import net.bisosrs.profileexport.mapping.StatsCollector;
import net.bisosrs.profileexport.util.JsonSerializer;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemManager;

@Singleton
public class BisOsrsProfileExporter
{
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BisCatalog bisCatalog;

	@Inject
	private JsonSerializer jsonSerializer;

	public ExportResult exportProfile()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return ExportResult.failure("Log in to export your BIS OSRS profile.");
		}

		String accountType = AccountTypeMapper.map(client);
		BisOsrsStats stats = StatsCollector.collect(client);
		List<String> quests = QuestCollector.collectCompletedQuestIds(client, bisCatalog);
		List<BisOsrsDiaryTier> diaries = DiaryCollector.collectCompletedDiaryTiers(client, bisCatalog);
		OwnedItemExport owned = EquippedUntradeablesCollector.collect(client, itemManager);

		List<String> notes = new ArrayList<>();
		notes.add("Exported from RuneLite (BIS OSRS Quest Exporter v1).");
		notes.add("Unlocks are not exported in v1 — set them manually in BIS OSRS.");
		notes.add("Owned items include equipped untradeables only (not bank or inventory).");
		if (!diaries.isEmpty())
		{
			notes.add("Diary tiers use threshold-based varbit completion for BIS-catalog regions only.");
		}

		BisOsrsProfile profile = BisOsrsProfile.builder()
			.version(BisOsrsProfile.EXPORT_VERSION)
			.source(BisOsrsProfile.EXPORT_SOURCE)
			.exportedAt(Instant.now().toString())
			.notes(String.join(" ", notes))
			.stats(stats)
			.completedQuestIds(quests)
			.completedDiaryTiers(diaries)
			.completedUnlockIds(Collections.emptyList())
			.ownedItemIds(owned.getIds())
			.ownedItemNames(owned.getNames())
			.ownedItemLines(owned.getLines())
			.accountType(accountType)
			.schemaVersionLabel(BisOsrsProfile.SCHEMA_VERSION_LABEL)
			.build();

		ExportSummary summary = ExportSummary.builder()
			.statsExported(StatsCollector.exportedStatCount(stats))
			.questsExported(quests.size())
			.diariesExported(diaries.size())
			.ownedItemsExported(owned.getIds().size())
			.accountTypeLabel(AccountTypeMapper.displayLabel(accountType))
			.statusMessage("Ready to copy or save.")
			.build();

		return ExportResult.success(profile, summary, jsonSerializer.toJson(profile));
	}

	@lombok.Value
	public static class ExportResult
	{
		boolean ok;
		String message;
		BisOsrsProfile profile;
		ExportSummary summary;
		String json;

		static ExportResult success(BisOsrsProfile profile, ExportSummary summary, String json)
		{
			return new ExportResult(true, summary.getStatusMessage(), profile, summary, json);
		}

		static ExportResult failure(String message)
		{
			return new ExportResult(false, message, null, null, null);
		}
	}
}

