package net.bisosrs.profileexport.mapping;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Varbits;

public final class AccountTypeMapper
{
	private AccountTypeMapper()
	{
	}

	public static String map(Client client)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return "unknown";
		}

		int value = client.getVarbitValue(Varbits.ACCOUNT_TYPE);
		switch (value)
		{
			case 0:
				return "normal";
			case 1:
				return "ironman";
			case 2:
				return "ultimate_ironman";
			case 3:
				return "hardcore_ironman";
			case 4:
			case 5:
			case 6:
				return "group_ironman";
			default:
				return "unknown";
		}
	}

	public static String displayLabel(String accountType)
	{
		switch (accountType)
		{
			case "normal":
				return "Normal";
			case "ironman":
				return "Ironman";
			case "ultimate_ironman":
				return "Ultimate Ironman";
			case "hardcore_ironman":
				return "Hardcore Ironman";
			case "group_ironman":
				return "Group Ironman";
			default:
				return "Unknown";
		}
	}
}

package net.bisosrs.profileexport.mapping;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Quest;

@Singleton
public final class BisCatalog
{
	private final Map<Quest, String> questIdsByQuest;
	private final List<String> diaryIds;

	@Inject
	BisCatalog(Gson gson)
	{
		InputStream stream = BisCatalog.class.getResourceAsStream("/bis_catalog.json");
		if (stream == null)
		{
			throw new IllegalStateException("Missing bis_catalog.json resource");
		}

		CatalogFile file = gson.fromJson(
			new InputStreamReader(stream, StandardCharsets.UTF_8),
			CatalogFile.class
		);

		Map<Quest, String> quests = new LinkedHashMap<>();
		for (CatalogQuest entry : file.quests)
		{
			try
			{
				Quest quest = Quest.valueOf(entry.runeliteQuest);
				quests.put(quest, entry.id);
			}
			catch (IllegalArgumentException ignored)
			{
				// Unknown quest enum — skip rather than fail export.
			}
		}

		List<String> diaries = file.diaries == null
			? Collections.emptyList()
			: file.diaries.stream().map(d -> d.id).collect(java.util.stream.Collectors.toList());

		this.questIdsByQuest = Collections.unmodifiableMap(quests);
		this.diaryIds = List.copyOf(diaries);
	}

	public Map<Quest, String> questIdsByQuest()
	{
		return questIdsByQuest;
	}

	public List<String> diaryIds()
	{
		return diaryIds;
	}

	private static final class CatalogFile
	{
		List<CatalogQuest> quests;
		List<CatalogDiary> diaries;
	}

	private static final class CatalogQuest
	{
		String id;

		@SerializedName("runeliteQuest")
		String runeliteQuest;
	}

	private static final class CatalogDiary
	{
		String id;
	}
}

package net.bisosrs.profileexport.mapping;

import java.util.ArrayList;
import java.util.List;
import net.bisosrs.profileexport.BisOsrsDiaryTier;
import net.runelite.api.Client;
import net.runelite.api.GameState;

public final class DiaryCollector
{
	private DiaryCollector()
	{
	}

	public static List<BisOsrsDiaryTier> collectCompletedDiaryTiers(Client client, BisCatalog catalog)
	{
		List<BisOsrsDiaryTier> completed = new ArrayList<>();
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return completed;
		}

		for (DiaryTierThreshold threshold : DiaryTierThreshold.ENTRIES)
		{
			if (threshold.getConfidence() != DiaryTierThreshold.ThresholdConfidence.HIGH)
			{
				continue;
			}

			if (!catalog.diaryIds().contains(threshold.getDiaryId()))
			{
				continue;
			}

			int value = client.getVarbitValue(threshold.getVarbitId());
			if (threshold.isComplete(value))
			{
				completed.add(new BisOsrsDiaryTier(threshold.getDiaryId(), threshold.getTier()));
			}
		}

		return completed;
	}
}

package net.bisosrs.profileexport.mapping;

import lombok.Value;
import net.runelite.api.Varbits;

@Value
public class DiaryTierThreshold
{
	String diaryId;
	String tier;
	int varbitId;
	int taskCount;
	ThresholdConfidence confidence;

	public boolean isComplete(int varbitValue)
	{
		if (taskCount <= 0 || taskCount > 30)
		{
			return false;
		}

		int fullMask = (1 << taskCount) - 1;
		return varbitValue > 0 && (varbitValue & fullMask) == fullMask;
	}

	public enum ThresholdConfidence
	{
		HIGH,
		LOW
	}

	static DiaryTierThreshold of(String diaryId, String tier, int varbitId, int taskCount, ThresholdConfidence confidence)
	{
		return new DiaryTierThreshold(diaryId, tier, varbitId, taskCount, confidence);
	}

	static final DiaryTierThreshold[] ENTRIES = {
		// Karamja — OSRS wiki task counts; bitmask completion (all bits set).
		of("karamja", "easy", Varbits.DIARY_KARAMJA_EASY, 10, ThresholdConfidence.HIGH),
		of("karamja", "medium", Varbits.DIARY_KARAMJA_MEDIUM, 19, ThresholdConfidence.HIGH),
		of("karamja", "hard", Varbits.DIARY_KARAMJA_HARD, 17, ThresholdConfidence.HIGH),
		of("karamja", "elite", Varbits.DIARY_KARAMJA_ELITE, 5, ThresholdConfidence.HIGH),

		// Kourend & Kebos — mapped to BIS id kourend_kebos.
		of("kourend_kebos", "easy", Varbits.DIARY_KOUREND_EASY, 12, ThresholdConfidence.HIGH),
		of("kourend_kebos", "medium", Varbits.DIARY_KOUREND_MEDIUM, 13, ThresholdConfidence.HIGH),
		of("kourend_kebos", "hard", Varbits.DIARY_KOUREND_HARD, 10, ThresholdConfidence.HIGH),
		of("kourend_kebos", "elite", Varbits.DIARY_KOUREND_ELITE, 8, ThresholdConfidence.HIGH),

		// Western Provinces.
		of("western_provinces", "easy", Varbits.DIARY_WESTERN_EASY, 11, ThresholdConfidence.HIGH),
		of("western_provinces", "medium", Varbits.DIARY_WESTERN_MEDIUM, 13, ThresholdConfidence.HIGH),
		of("western_provinces", "hard", Varbits.DIARY_WESTERN_HARD, 13, ThresholdConfidence.HIGH),
		of("western_provinces", "elite", Varbits.DIARY_WESTERN_ELITE, 7, ThresholdConfidence.HIGH),
	};
}

package net.bisosrs.profileexport.mapping;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

public final class EquippedUntradeablesCollector
{
	public static final class OwnedItemExport
	{
		private final List<Integer> ids = new ArrayList<>();
		private final List<String> names = new ArrayList<>();

		public List<Integer> getIds()
		{
			return ids;
		}

		public List<String> getNames()
		{
			return names;
		}

		public List<String> getLines()
		{
			List<String> lines = new ArrayList<>();
			for (int i = 0; i < ids.size(); i++)
			{
				lines.add(String.valueOf(ids.get(i)));
				lines.add(names.get(i));
			}
			return lines;
		}
	}

	private EquippedUntradeablesCollector()
	{
	}

	public static OwnedItemExport collect(Client client, ItemManager itemManager)
	{
		OwnedItemExport export = new OwnedItemExport();
		if (client == null || itemManager == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return export;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return export;
		}

		Set<Integer> seen = new LinkedHashSet<>();
		for (Item item : equipment.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}

			int itemId = item.getId();
			if (!seen.add(itemId))
			{
				continue;
			}

			ItemComposition composition = itemManager.getItemComposition(itemId);
			if (composition == null || composition.isTradeable())
			{
				continue;
			}

			export.ids.add(itemId);
			export.names.add(composition.getName());
		}

		return export;
	}
}

package net.bisosrs.profileexport.mapping;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

public final class QuestCollector
{
	private QuestCollector()
	{
	}

	public static List<String> collectCompletedQuestIds(Client client, BisCatalog catalog)
	{
		List<String> completed = new ArrayList<>();
		Map<Quest, String> questCatalog = catalog.questIdsByQuest();

		for (Map.Entry<Quest, String> entry : questCatalog.entrySet())
		{
			Quest quest = entry.getKey();
			if (quest.getState(client) == QuestState.FINISHED)
			{
				completed.add(entry.getValue());
			}
		}

		completed.sort(String::compareTo);
		return completed;
	}
}

package net.bisosrs.profileexport.mapping;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.bisosrs.profileexport.BisOsrsStats;

public final class StatsCollector
{
	private StatsCollector()
	{
	}

	public static BisOsrsStats collect(Client client)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return BisOsrsStats.empty();
		}

		return BisOsrsStats.builder()
			.attack(client.getRealSkillLevel(Skill.ATTACK))
			.strength(client.getRealSkillLevel(Skill.STRENGTH))
			.defence(client.getRealSkillLevel(Skill.DEFENCE))
			.ranged(client.getRealSkillLevel(Skill.RANGED))
			.magic(client.getRealSkillLevel(Skill.MAGIC))
			.prayer(client.getRealSkillLevel(Skill.PRAYER))
			.hitpoints(client.getRealSkillLevel(Skill.HITPOINTS))
			.build();
	}

	public static int exportedStatCount(BisOsrsStats stats)
	{
		return 7;
	}
}

package net.bisosrs.profileexport.util;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import javax.swing.JFileChooser;
import javax.swing.filechooser.FileNameExtensionFilter;
import net.runelite.client.util.Text;

public final class ExportActions
{
	private ExportActions()
	{
	}

	public static void copyToClipboard(String json)
	{
		StringSelection selection = new StringSelection(json);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, selection);
	}

	public static File saveToFile(String json, String usernameHint) throws IOException
	{
		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Save BIS OSRS profile JSON");
		chooser.setSelectedFile(new File(defaultFilename(usernameHint)));
		chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

		int result = chooser.showSaveDialog(null);
		if (result != JFileChooser.APPROVE_OPTION)
		{
			return null;
		}

		File file = chooser.getSelectedFile();
		if (!file.getName().toLowerCase().endsWith(".json"))
		{
			file = new File(file.getAbsolutePath() + ".json");
		}

		Files.writeString(file.toPath(), json, StandardCharsets.UTF_8);
		return file;
	}

	public static String defaultFilename(String usernameHint)
	{
		String safe = Text.standardize(usernameHint == null ? "" : usernameHint)
			.replace(' ', '-')
			.replaceAll("[^a-zA-Z0-9\\-_]", "");
		if (safe.isEmpty())
		{
			return "bisosrs-profile.json";
		}
		return "bisosrs-profile-" + safe + ".json";
	}
}

